import{_ as t,o as s,c as n,a2 as a}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Troubleshooting","description":"Common errors and solutions when running AzureScout.","frontmatter":{"description":"Common errors and solutions when running AzureScout."},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),o={name:"troubleshooting.md"};function i(r,e,d,l,c,p){return s(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="common-errors" tabindex="-1">Common Errors <a class="header-anchor" href="#common-errors" aria-label="Permalink to &quot;Common Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Error</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Insufficient privileges to complete the operation</code></td><td>Missing Microsoft Graph permission</td><td>Grant the required permission and perform admin consent. See <a href="./permissions.html">Permissions</a>.</td></tr><tr><td><code>Authorization_RequestDenied</code></td><td>Delegated permission not consented</td><td>Sign in with a Global Admin and consent to the required permissions.</td></tr><tr><td><code>Resource provider not registered</code> / <code>[FAIL] Provider: ... NotRegistered</code></td><td>Provider not enabled in subscription</td><td><strong>This is expected.</strong> Not all providers need to be registered in every subscription — Azure only registers providers for services you actually use. The corresponding inventory modules are simply skipped. Only register a provider if you actually use that service and want it included in the report: <code>Register-AzResourceProvider -ProviderNamespace &lt;namespace&gt;</code>. See <a href="./prerequisites.html">Prerequisites</a> for details.</td></tr><tr><td><code>No match was found for the specified search criteria and module name</code></td><td>Module not available in PSGallery or network restrictions</td><td>Install the module manually. See <a href="./prerequisites.html">Prerequisites</a> for install commands.</td></tr><tr><td><code>Get-AzSubscription returned 0 subscriptions</code></td><td>Identity has no Reader role on any subscription</td><td>Assign <code>Reader</code> at the subscription or management group level.</td></tr><tr><td><code>Connect-AzAccount: interactive login failed</code></td><td>Running in a non-interactive session (CI/CD, SSH)</td><td>Use <code>-DeviceLogin</code>, SPN with secret, or SPN with certificate. See <a href="./authentication.html">Authentication</a>.</td></tr><tr><td><code>Token acquisition failed for MSGraph</code></td><td>Az.Accounts version too old or tenant configuration issue</td><td>Update <code>Az.Accounts</code> to latest: <code>Update-Module Az.Accounts -Force</code></td></tr><tr><td><code>Export-Excel: file is locked</code></td><td>Excel report file is open in another application</td><td>Close the file and re-run.</td></tr><tr><td>Management Groups worksheet is empty, no error</td><td>Identity has no tenant-root role</td><td>Assign <code>Management Group Reader</code> at the tenant root. Since v2.3.0 the login summary reports the visible count and prints this tip, so you find out at sign-in rather than after the run.</td></tr><tr><td>Reports are not where a previous version left them</td><td>Run isolation (v2.3.0)</td><td>Each run now writes to its own folder under the base path. Use <code>-Force</code> for the old overwrite-in-place behaviour, or <code>-RunName</code> to control the folder name. See <a href="./output.html#run-isolation">Output Files &amp; Formats</a>.</td></tr><tr><td>Output folders accumulating on disk</td><td>One folder per run, by design</td><td><code>Clear-AZSCCacheFolder -OlderThan 30</code> prunes runs not written to in the last 30 days.</td></tr><tr><td><code>No Azure DevOps organizations could be discovered</code></td><td>Service principals have no profile to enumerate</td><td>Pass <code>-DevOpsOrganization &#39;contoso&#39;,&#39;fabrikam&#39;</code>. See <a href="./azure-devops.html">Azure DevOps</a>.</td></tr><tr><td><code>Could not acquire an Azure DevOps token</code></td><td>Not signed in, or the sign-in cannot reach Azure DevOps</td><td>Run <code>Connect-AzAccount</code>, or pass <code>-DevOpsPat</code>.</td></tr><tr><td>ADO Service Connections worksheet missing</td><td>Identity holds project read but not service connection read</td><td>Expected and handled — that slice is skipped and the rest still collects. Grant the scope to include it.</td></tr><tr><td>Runbook uploads fail with <code>blob already exists</code></td><td>Module older than v2.3.0</td><td>Upgrade. Uploads now pass <code>-Force</code>, so a second scheduled run overwrites rather than failing. See <a href="./automation.html">Azure Automation Account</a>.</td></tr><tr><td>Chart step fails on a GitHub-hosted runner</td><td>Chart customization drives Excel over COM; no hosted runner has Excel</td><td>Keep <code>lite: true</code> in the action. See <a href="./github-actions.html">GitHub Actions</a>.</td></tr><tr><td><code>The term &#39;Invoke-AzCostManagementQuery&#39; is not recognized</code></td><td><code>Az.CostManagement</code> missing, and before v2.5.3 <code>-IncludeCosts</code> treated that as fatal</td><td>Upgrade. Since v2.5.3 the run continues without cost data and warns instead. To collect costs, <code>Install-Module Az.CostManagement -Scope CurrentUser</code>.</td></tr><tr><td><code>The property &#39;&lt;name&gt;&#39; cannot be found on this object</code> during extraction</td><td>Module older than v2.5.3</td><td>Upgrade. This was a StrictMode member-enumeration fault that fired whenever an Azure API returned an empty result for <strong>every</strong> subscription — see <a href="./changelog.html">Changelog</a>.</td></tr></tbody></table><h2 id="run-logs" tabindex="-1">Run logs <a class="header-anchor" href="#run-logs" aria-label="Permalink to &quot;Run logs&quot;">​</a></h2><p><strong>Every run writes a detailed log into its own run folder — you do not have to ask for it.</strong> When something goes wrong, read the log before re-running anything.</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>scout-run.log</code></td><td>Structured log: run metadata header, every phase boundary with elapsed time, per-phase counts, warnings, and — when a run fails — the full error record including the failing script, line number and script stack trace</td></tr><tr><td><code>scout-console.log</code></td><td>Transcript of everything printed to the console, warnings included. Skipped on hosts that do not support transcription (including Azure Automation)</td></tr></tbody></table><p>Both land next to the report:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\you\\Documents\\AzureScout\\2026-07-25_152431_d6fc73cf\\</span></span>
<span class="line"><span>├── scout-run.log</span></span>
<span class="line"><span>├── scout-console.log</span></span>
<span class="line"><span>└── AzureScout_Report_2026-07-25_15_24.xlsx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>A failed run prints the log path before it exits:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  The run failed. Full detail written to: C:\\...\\2026-07-25_152431_d6fc73cf\\scout-run.log</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The failure block in <code>scout-run.log</code> looks like this — the script and line are the fastest route to a diagnosis, and are exactly what a bare console error does not give you:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2026-07-25 15:58:09.445] [ERROR] ---------------- RUN FAILED ----------------</span></span>
<span class="line"><span>[2026-07-25 15:58:09.476] [ERROR] Message    : The term &#39;Invoke-AzCostManagementQuery&#39; is not recognized...</span></span>
<span class="line"><span>[2026-07-25 15:58:09.587] [ERROR] Script     : ...\\Modules\\Private\\Extraction\\Get-AZTICostInventory.ps1</span></span>
<span class="line"><span>[2026-07-25 15:58:09.620] [ERROR] Line       : 49</span></span>
<span class="line"><span>[2026-07-25 15:58:09.682] [ERROR] ScriptStackTrace :</span></span>
<span class="line"><span>[2026-07-25 15:58:09.711] [ERROR]     at Get-AZSCCostInventory, ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Logging is best-effort by design: if the log cannot be written the run still proceeds, warning once. A lost log is a lost diagnostic, never a lost report.</p><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h2><p>For step-by-step tracing beyond the run log, enable debug output:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-AzureScout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Debug</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>This produces timestamped log entries for each extraction step, module execution, and API call.</p><h2 id="pre-flight-permission-check" tabindex="-1">Pre-flight Permission Check <a class="header-anchor" href="#pre-flight-permission-check" aria-label="Permalink to &quot;Pre-flight Permission Check&quot;">​</a></h2><p>Run the permission checker standalone to validate access before a full inventory:</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Test-AZSCPermissions</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TenantID </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;00000000-...&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope All</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$result </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Format-List</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The <code>Details</code> array contains per-check results with remediation guidance for any failures.</p>`,21)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
